targets.root_selector:
(
  $cols := properties.columns.name;
  $recs := $map(properties.rows, function($r) { $merge($map($cols, function($c, $i) { {$c: $r[$i]} })) });
  $p0 := ${__from};
  $p1 := ${__to};
  $bud := $number("${budget}");
  $period := $round(($p1 - $p0) / 86400000);
  $days := $max([$count($keys($merge($map($recs.UsageDate, function($d) { {$string($d): 1} })))), 1]);
  $tot := $sum($recs.Cost);
  [$map($recs, function($x) {(
    $s := $string($x.UsageDate);
    $t := $toMillis($substring($s, 0, 4) & "-" & $substring($s, 4, 2) & "-" & $substring($s, 6, 2) & "T00:00:00.000Z");
    $dop := $floor(($t - $p0) / 86400000) + 1;
    {
      "Date": $t,
      "Domain": $x.TagValue ? $x.TagValue : "(senza tag)",
      "Cost": $x.Cost,
      "Currency": $x.Currency,
      "DailyAvg": $x.Cost / $days,
      "ForecastCost": $x.Cost * $period / $days,
      "SharePct": $tot > 0 ? $x.Cost / $tot * 100 : 0,
      "BudgetPct": $x.Cost / $bud * 100,
      "ForecastBudgetPct": $x.Cost * $period / $days / $bud * 100,
      "DayOfPeriod": $dop,
      "IdealCumulative": $bud / $period * $dop,
      "Budget": $bud
    }
  )})]
)

(
  $cols := properties.columns.name;
  $recs := $map(properties.rows, function($r) { $merge($map($cols, function($c, $i) { {$c: $r[$i]} })) });
  $tot := $sum($recs.Cost);
  [$map($recs, function($x) {{
    "Resource": $x.ResourceId ? $split($x.ResourceId, "/")[-1] : "(non attribuito)",
    "ResourceId": $x.ResourceId,
    "Domain": $x.TagValue ? $x.TagValue : "(senza tag)",
    "ResourceGroup": $x.ResourceGroup ? $lowercase($x.ResourceGroup) : "(nessuno)",
    "ServiceName": $x.ServiceName,
    "ServiceTier": $x.ServiceTier,
    "Meter": $x.Meter,
    "ChargeType": $x.ChargeType,
    "Pricing": $x.BenefitName ? "Reservation / Savings plan" : "Pay-as-you-go",
    "Benefit": $x.BenefitName,
    "Cost": $x.Cost,
    "SharePct": $tot > 0 ? $x.Cost / $tot * 100 : 0
  }})]
)
